import json
import re
from datetime import datetime, timedelta

# Parse Alice's schedule (UNAVAILABLE_PERIODS)
# Available = all dates NOT in the unavailable periods
alice_unavailable = []
with open('/app/alice_schedule.txt', 'r') as f:
    for line in f:
        line = line.strip()
        if line.startswith('UNAVAILABLE:'):
            # Format: UNAVAILABLE: 2025-01-01 to 2025-06-15 (School semester)
            match = re.match(r'UNAVAILABLE:\s+(\d{4}-\d{2}-\d{2})\s+to\s+(\d{4}-\d{2}-\d{2})', line)
            if match:
                start = datetime.strptime(match.group(1), '%Y-%m-%d')
                end = datetime.strptime(match.group(2), '%Y-%m-%d')
                alice_unavailable.append((start, end))

alice_free = []
for d in range(10000):
    d_date = datetime(2025, 1, 1) + timedelta(days=d)
    free = True
    for unavail in alice_unavailable:
        if unavail[0] <= d_date <= unavail[1]:
            free = False
            break
    if free:
        alice_free.append(d_date)

# Parse Bob's schedule (SHIFT_CSV)
bob_shifts = []
with open('/app/bob_schedule.txt', 'r') as f:
    for line in f:
        line = line.strip()
        if line.startswith('SHIFT:'):
            parts = line.split(':', 1)[1].strip()
            bob_shifts.append(parts)

bob_free = []
for shift in bob_shifts:
    parts = shift.split(',')
    date = datetime.strptime(parts[0], '%Y-%m-%d')
    status = parts[1].strip()
    if status == 'off,rest':
        bob_free.append(date)

# Parse Charlie's schedule (TRAVEL_TEXT)
# BUSY periods are unavailable, available = dates NOT in BUSY
charlie_unavailable = []
with open('/app/charlie_schedule.txt', 'r') as f:
    for line in f:
        line = line.strip()
        if line.startswith('BUSY:'):
            # Format: BUSY: 2025-01-01 to 2025-06-10 (Kids school year)
            match = re.match(r'BUSY:\s+(\d{4}-\d{2}-\d{2})\s+to\s+(\d{4}-\d{2}-\d{2})', line)
            if match:
                start = datetime.strptime(match.group(1), '%Y-%m-%d')
                end = datetime.strptime(match.group(2), '%Y-%m-%d')
                charlie_unavailable.append((start, end))

charlie_free = []
for d in range(10000):
    d_date = datetime(2025, 1, 1) + timedelta(days=d)
    free = True
    for unavail in charlie_unavailable:
        if unavail[0] <= d_date <= unavail[1]:
            free = False
            break
    if free:
        charlie_free.append(d_date)

# Parse Dana's schedule (MIXED_JSON)
dana_unavailable = []
with open('/app/dana_schedule.txt', 'r') as f:
    for line in f:
        line = line.strip()
        if line.startswith('BUSY:'):
            # Format: BUSY: 2025-01-01 to 2025-06-10 (Kids school year)
            match = re.match(r'BUSY:\s+(\d{4}-\d{2}-\d{2})\s+to\s+(\d{4}-\d{2}-\d{2})', line)
            if match:
                start = datetime.strptime(match.group(1), '%Y-%m-%d')
                end = datetime.strptime(match.group(2), '%Y-%m-%d')
                dana_unavailable.append((start, end))

# Now create availability lists

def get_ranges(dates):
    if not dates:
        return []
    sorted_dates = sorted(dates)
    ranges = []
    current_start = sorted_dates[0]
    current_end = sorted_dates[0]
    for d in sorted_dates[1:]:
        if d == current_end + timedelta(days=1):
            current_end = d
        else:
            ranges.append((current_start, current_end))
            current_start = d
            current_end = d
    ranges.append((current_start, current_end))
    return ranges

# Alice
alice_free_ranges = get_ranges(alice_free)
# Bob
bob_free_ranges = get_ranges(bob_free)
# Charlie
charlie_free_ranges = get_ranges(charlie_free)
# Dana

dana_free = []
for d in range(10000):
    d_date = datetime(2025, 1, 1) + timedelta(days=d)
    free = True
    for unavail in dana_unavailable:
        if unavail[0] <= d_date <= unavail[1]:
            free = False
            break
    if free:
        dana_free.append(d_date)

dana_free_ranges = get_ranges(dana_free)

# Now convert to the required format: list of {"start": "YYYY-MM-DD", "end": "YYYY-MM-%d"}
result = {}

result['alice'] = []
for s, e in alice_free_ranges:
    result['alice'].append({'start': s.strftime('%Y-%m-%d'), 'end': e.strftime('%Y-%m-%d')})

result['bob'] = []
for s, e in bob_free_ranges:
    result['bob'].append({'start': s.strftime('%Y-%m-%d'), 'end': e.strftime('%Y-%m-%d')})

result['charlie'] = []
for s, e in charlie_free_ranges:
    result['charlie'].append({'start': s.strftime('%Y-%m-%d'), 'end': e.strftime('%Y-%m-%d')})

result['dana'] = []
for s, e in dana_free_ranges:
    result['dana'].append({'start': s.strftime('%Y-%m-%d'), 'end': e.strftime('%Y-%m-%d')})

with open('/app/all_availability.json', 'w') as f:
    json.dump(result, f, indent=2)

print("all_availability.json created:")
print(json.dumps(result, indent=2))
